-- =====================================================
-- Room Ready Supply — Product Seed
-- Paste this entire script into:
--   Supabase Dashboard → SQL Editor → New Query → Run
-- =====================================================

ON CONFLICT (slug) DO UPDATE SET
  name          = EXCLUDED.name,
  sku           = EXCLUDED.sku,
  category_name = EXCLUDED.category_name,
  description   = EXCLUDED.description,
  price         = EXCLUDED.price,
  unit          = EXCLUDED.unit,
  case_qty      = EXCLUDED.case_qty,
  image_url     = EXCLUDED.image_url,
  is_active     = EXCLUDED.is_active,
  updated_at    = NOW();

-- Create inventory records for all products (default: in_stock, qty 100)
SELECT id, 100, 'in_stock', NOW()
FROM products
ON CONFLICT (product_id) DO NOTHING;

SELECT COUNT(*) AS products_total FROM products;
SELECT COUNT(*) AS inventory_total FROM inventory;
